files.guard.yaml:
version: 1
metrics:
  source: [src]
  profiles:
    standard:
      limits:
        file: {lines: 1, ncloc: 1}
        class: {lines: 1}
        method: {lines: 1, cyclomatic_complexity: 1}
  default: standard
structure:
  paths: [src]
  directories:
    - {path: 'src', allow: ['*.php'], require: [Required.php], max_files: 1}
documentation:
  files:
    README.md: {headings: ['# Expected', '## Details']}
    MISSING.md: {headings: ['# Missing']}
  scan: ['**/*.md']
configuration:
  - {id: count, file: app.json, select: /count, assert: {min: 1}, repair: 2}
  - {id: mode, file: app.json, select: /mode, level: recommended, assert: {equals: new}}

all-policies.output:
{
    "findings": [
        {
            "path": "src/Example.php",
            "rule": "metrics.file_lines",
            "level": "error",
            "message": "File has 4 physical lines; maximum is 1."
        },
        {
            "path": "src/Example.php",
            "rule": "metrics.file_ncloc",
            "level": "error",
            "message": "File has 3 non-comment lines of code; maximum is 1."
        },
        {
            "path": "src/Example.php",
            "rule": "metrics.class_lines",
            "level": "error",
            "message": "class Example has 3 physical lines; maximum is 1."
        },
        {
            "path": "src/Example.php",
            "rule": "metrics.cyclomatic_complexity",
            "level": "error",
            "message": "method Example::run has cyclomatic complexity 2; maximum is 1."
        },
        {
            "path": "src",
            "rule": "structure.max_files",
            "level": "error",
            "message": "Directory \"src\" contains 2 files but the limit is 1. Move or merge files until at most 1 remain."
        },
        {
            "path": "src/bad.txt",
            "rule": "structure.disallowed_file",
            "level": "error",
            "message": "File \"src/bad.txt\" does not match any allowed pattern (*.php). Rename, move, or delete it."
        },
        {
            "path": "src/Required.php",
            "rule": "structure.missing_required_file",
            "level": "error",
            "message": "Directory \"src\" is missing required file \"Required.php\". Create it."
        },
        {
            "path": "README.md",
            "rule": "documentation.changed_heading_level",
            "level": "error",
            "message": "Heading \"### Details\" is level 3, but guard.yaml declares \"## Details\" at level 2 in README.md. Restore the declared level; changing the nesting of sections requires a human to update guard.yaml."
        },
        {
            "path": "README.md",
            "rule": "documentation.renamed_heading",
            "level": "error",
            "message": "Heading \"# Wrong\" replaces the declared heading \"# Expected\" in README.md. Restore the declared heading and edit only the section content; renaming a section requires a human to update guard.yaml."
        },
        {
            "path": "MISSING.md",
            "rule": "documentation.missing_document",
            "level": "error",
            "message": "Declared document MISSING.md does not exist. Restore the document; removing or renaming a document requires a human to update guard.yaml."
        },
        {
            "path": "docs/extra.md",
            "rule": "documentation.undeclared_document",
            "level": "error",
            "message": "Document docs/extra.md matches the scan pattern \"**/*.md\" but is not declared in guard.yaml. Move its content into an existing section of a declared document and delete the file; adding a document requires a human to update guard.yaml."
        },
        {
            "path": "app.json",
            "rule": "count",
            "level": "error",
            "message": "/count must satisfy {\"min\":1}. Run guard apply to set the configured repair."
        },
        {
            "path": "app.json",
            "rule": "mode",
            "level": "warning",
            "message": "/mode must satisfy {\"equals\":\"new\"}. Run guard apply to set the configured repair."
        }
    ],
    "changes": [],
    "action": "blocked",
    "success": false
}

